{"version":3,"sources":["../scss/profileShop.scss","profileShop.css","../scss/_mixins.scss","../scss/_variables.scss"],"names":[],"mappings":"AAGA;EACE,cAAA;ACFF;;ADKA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;ACFF;;ADKA;EACE,aAAA;EACA,uBAAA;EACA,8BAAA;EACA,SAAA;EACA,oBAAA;EACA,gCAAA;ACFF;;ADME;EEtBE,uCAAA;EACA,gBFsBoC;EErBpC,kBAAA;EACA,YCHW;EDIX,eFmB8B;EAC9B,mBAAA;ACCJ;;ADGA;EACE,eAAA;ACAF;ADEE;EACE,WAAA;EACA,YAAA;EACA,oBAAA;KAAA,iBAAA;EACA,0BAAA;KAAA,uBAAA;ACAJ;;ADIA;EACE,aAAA;EACA,SAAA;EACA,mBAAA;EACA,mBAAA;ACDF;ADGE;EE7CE,uCAAA;EACA,gBF6CiC;EE5CjC,kBAAA;EACA,cCJQ;EDKR,eF0C2B;ACG/B;ADDI;EACE,UGhDO;AFmDb;;ADEA;EEtDI,uCAAA;EACA,gBFsDkC;EErDlC,kBAAA;EACA,YCHW;EDIX,eFmD4B;EAC9B,mBAAA;ACKF;ADHE;EACE,WAAA;EACA,gBAAA;ACKJ;;ADDA;EEhEI,uCAAA;EACA,gBFgEkC;EE/DlC,kBAAA;EACA,YCHW;EDIX,eF6D4B;EAC9B,mBAAA;ACQF;ADNE;EACE,WAAA;EACA,gBAAA;ACQJ;ADNI;EACE,YAAA;ACQN;;ADHA;EE9EI,uCAAA;EACA,gBF8E+B;EE7E/B,kBAAA;EACA,cCJQ;EDKR,eF2EyB;EAC3B,mBAAA;EACA,qBAAA;ACUF;ADRE;EACE,UGnFS;AF6Fb;;ADNA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;ACSF;ADPE;EE7FE,uCAAA;EACA,gBF6FoC;EE5FpC,kBAAA;EACA,YCHW;EDIX,eF0F8B;EAC9B,eAAA;ACaJ;ADVE;EElGE,uCAAA;EACA,gBFkGoC;EEjGpC,kBAAA;EACA,YCHW;EDIX,eF+F8B;EAC9B,sBAAA;ACgBJ;ADbE;EACE,aAAA;EACA,uBAAA;EACA,SAAA;ACeJ;ADbI;EE5GA,uCAAA;EACA,gBF4GmC;EE3GnC,kBAAA;EACA,cCJQ;EDKR,eFyG6B;ACmBjC;ADjBM;EACE,UG/GK;AFkIb;;ADbA;EEtHI,uCAAA;EACA,gBFsHgC;EErHhC,kBAAA;EACA,UCFS;EDGT,eFmH0B;EAC5B,mBAAA;ACoBF;;ADjBA;EE3HI,uCAAA;EACA,gBF2HoC;EE1HpC,kBAAA;EACA,qBCMa;EDLb,eFwH8B;EAChC,mBAAA;ACwBF;;ADrBA;EACE,aAAA;EACA,SAAA;EACA,mBAAA;ACwBF;;ADrBA;EEtII,uCAAA;EACA,gBFsI+B;EErI/B,kBAAA;EACA,cCJQ;EDKR,eFmIyB;EAC3B,qBAAA;EACA,gBAAA;EACA,6BAAA;EACA,gBAAA;EACA,YAAA;EACA,eAAA;AC4BF;AD3BE;EACE,UG9IS;AF2Kb;AD3BE;EACE,uBAAA;AC6BJ","file":"profileShop.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n.main__wrapper {\n  flex: 1 1 auto;\n}\n\n.main__shop-list {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.main__shop-list-item {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 15px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid $gray;\n}\n\n.main__shop-list-item-text {\n  & h3 {\n    @include fonts($defaultColor, 18px, 600);\n    margin-bottom: 15px;\n  }\n}\n\n.main__shop-list-item-img {\n  flex: 0 0 200px;\n\n  & img {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    object-position: center;\n  }\n}\n\n.main__shop-list-item-edit {\n  display: flex;\n  gap: 10px;\n  align-items: center;\n  margin-bottom: 10px;\n\n  & a {\n    @include fonts($mainColor, 14px, 400);\n\n    &:hover {\n      color: $colorHover;\n    }\n  }\n}\n\n.main__shop-list-item-registration {\n  @include fonts($defaultColor, 16px, 400);\n  margin-bottom: 10px;\n\n  & span {\n    color: blue;\n    font-weight: 600;\n  }\n}\n\n.main__shop-list-item-active {\n  @include fonts($defaultColor, 16px, 400);\n  margin-bottom: 10px;\n\n  & span {\n    color: blue;\n    font-weight: 600;\n\n    & span {\n      color: green;\n    }\n  }\n}\n\n.main__shop-list-item-shop-link {\n  @include fonts($mainColor, 14px, 400);\n  margin-bottom: 15px;\n  display: inline-block;\n\n  &:hover {\n    color: $colorHover;\n  }\n}\n\n.main__shop-list-item-about {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n\n  & h4 {\n    @include fonts($defaultColor, 14px, 600);\n    flex: 0 0 100px;\n  }\n\n  & p {\n    @include fonts($defaultColor, 14px, 400);\n    word-break: break-word;\n  }\n\n  & li {\n    display: flex;\n    align-items: flex-start;\n    gap: 10px;\n\n    & a {\n      @include fonts($mainColor, 14px, 400);\n\n      &:hover {\n        color: $colorHover;\n      }\n    }\n  }\n}\n\n.store__status {\n  @include fonts($colorHover, 14px, 400);\n  margin-bottom: 15px;\n}\n\n.store__active {\n  @include fonts($asideExitColor, 14px, 400);\n  margin-bottom: 15px;\n}\n\n.main__shop-list-item-title {\n  display: flex;\n  gap: 20px;\n  align-items: center;\n}\n\n.store__status-btn {\n  @include fonts($mainColor, 14px, 400);\n  display: inline-block;\n  box-shadow: none;\n  background-color: transparent;\n  background: none;\n  border: none;\n  cursor: pointer;\n  &:hover {\n    color: $colorHover;\n  }\n  &:focus {\n    border: none !important;\n  }\n}",".main__wrapper {\n  flex: 1 1 auto;\n}\n\n.main__shop-list {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n\n.main__shop-list-item {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 15px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid #D4D4D4;\n}\n\n.main__shop-list-item-text h3 {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 18px;\n  margin-bottom: 15px;\n}\n\n.main__shop-list-item-img {\n  flex: 0 0 200px;\n}\n.main__shop-list-item-img img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n.main__shop-list-item-edit {\n  display: flex;\n  gap: 10px;\n  align-items: center;\n  margin-bottom: 10px;\n}\n.main__shop-list-item-edit a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n}\n.main__shop-list-item-edit a:hover {\n  color: red;\n}\n\n.main__shop-list-item-registration {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n  margin-bottom: 10px;\n}\n.main__shop-list-item-registration span {\n  color: blue;\n  font-weight: 600;\n}\n\n.main__shop-list-item-active {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 16px;\n  margin-bottom: 10px;\n}\n.main__shop-list-item-active span {\n  color: blue;\n  font-weight: 600;\n}\n.main__shop-list-item-active span span {\n  color: green;\n}\n\n.main__shop-list-item-shop-link {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n  margin-bottom: 15px;\n  display: inline-block;\n}\n.main__shop-list-item-shop-link:hover {\n  color: red;\n}\n\n.main__shop-list-item-about {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n}\n.main__shop-list-item-about h4 {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  flex: 0 0 100px;\n}\n.main__shop-list-item-about p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  word-break: break-word;\n}\n.main__shop-list-item-about li {\n  display: flex;\n  align-items: flex-start;\n  gap: 10px;\n}\n.main__shop-list-item-about li a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n}\n.main__shop-list-item-about li a:hover {\n  color: red;\n}\n\n.store__status {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: red;\n  font-size: 14px;\n  margin-bottom: 15px;\n}\n\n.store__active {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: rgb(0, 128, 0);\n  font-size: 14px;\n  margin-bottom: 15px;\n}\n\n.main__shop-list-item-title {\n  display: flex;\n  gap: 20px;\n  align-items: center;\n}\n\n.store__status-btn {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n  display: inline-block;\n  box-shadow: none;\n  background-color: transparent;\n  background: none;\n  border: none;\n  cursor: pointer;\n}\n.store__status-btn:hover {\n  color: red;\n}\n.store__status-btn:focus {\n  border: none !important;\n}","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);"]}2;\n$asideExitColor: rgb(0, 128, 0);"]}